const indexed = [...ENTRIES].sort((a, b) => b[0].length - a[0].length);
const escape = (value: string): string => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const pattern = new RegExp(`(?<![A-Za-z])(?:${indexed.map((row) => escape(row[0])).join('|')})(?![A-Za-z])`, 'g');
const lookup = new Map(indexed.map((entry) => [entry[0], entry]));

/** Translates known UI phrases in one pass, preserving numbers, names and machine-readable file names. */
export function translateText(english: string, language: Language): string {
  if (language === 'en') return english;
  const column = LANGUAGES.indexOf(language);
  return english.replace(pattern, (match) => lookup.get(match)?.[column] ?? match);
}
